// TypeScript Version: 4.1

/* eslint-disable @typescript-eslint/unified-signatures */

/// <reference types="@stdlib/types"/>

import { Order, Mode, float64ndarray, Shape3D } from '@stdlib/types/ndarray';
import { Collection, AccessorArrayLike, ArrayLike } from '@stdlib/types/array';
import ArrayBuffer = require( '@stdlib/array/buffer' );

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Array order (either 'row-major' (C-style) or 'column-major' (Fortran-style)).
	*/
	order?: Order;

	/**
	* Specifies how to handle a linear index which exceeds array dimensions (default: 'throw').
	*/
	mode?: Mode;

	/**
	* Specifies how to handle subscripts which exceed array dimensions on a per dimension basis (default: ['throw']).
	*/
	submode?: ArrayLike<Mode>;

	/**
	* Boolean indicating whether an array should be read-only (default: false).
	*/
	readonly?: boolean;
}

/**
* Interface defining a typed three-dimensional ndarray constructor which is both "newable" and "callable".
*/
interface Float64Tensor3D {
	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D();
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 0, 0, 0 ]
	*/
	new ( options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param shape - ndarray shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( [ 1, 2, 2 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	new ( shape: Shape3D, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param K - number of elements in the first dimension
	* @param M - number of elements in the second dimension
	* @param N - number of elements in the last dimension
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( 1, 2, 2 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	new ( K: number, M: number, N: number, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param obj - array-like object or iterable from which to generate a three-dimensional ndarray
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( [ [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	new ( obj: ArrayLike<Collection<unknown> | AccessorArrayLike<unknown>> | Iterable<Collection<unknown> | AccessorArrayLike<unknown>>, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* ## Notes
	*
	* -   The returned ndarray view spans the entirety of the underlying ArrayBuffer and the two leading dimensions of the returned ndarray always have a size of one.
	*
	* @param buffer - underlying ArrayBuffer
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 1, 4 ]
	*/
	new ( buffer: ArrayBuffer, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* ## Notes
	*
	* -   The returned ndarray view spans from the byteOffset to the end of the underlying ArrayBuffer and the two leading dimensions of the returned ndarray always have a size of one.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 1, 3 ]
	*/
	new ( buffer: ArrayBuffer, byteOffset: number, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param shape - ndarray shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8, [ 1, 2, 1 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 1 ]
	*/
	new ( buffer: ArrayBuffer, byteOffset: number, shape: Shape3D, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param K - number of elements in the first dimension
	* @param M - number of elements in the second dimension
	* @param N - number of elements in the last dimension
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8, 1, 2, 1 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 1 ]
	*/
	new ( buffer: ArrayBuffer, byteOffset: number, K: number, M: number, N: number, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D();
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 0, 0, 0 ]
	*/
	( options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param shape - ndarray shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( [ 1, 2, 2 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	( shape: Shape3D, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param K - number of elements in the first dimension
	* @param M - number of elements in the second dimension
	* @param N - number of elements in the last dimension
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( 1, 2, 2 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	( K: number, M: number, N: number, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param obj - array-like object or iterable from which to generate a three-dimensional ndarray
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new Float64Tensor3D( [ [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 2 ]
	*/
	( obj: ArrayLike<Collection<unknown> | AccessorArrayLike<unknown>> | Iterable<Collection<unknown> | AccessorArrayLike<unknown>>, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* ## Notes
	*
	* -   The returned ndarray view spans the entirety of the underlying ArrayBuffer and the two leading dimensions of the returned ndarray always have a size of one.
	*
	* @param buffer - underlying ArrayBuffer
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 1, 4 ]
	*/
	( buffer: ArrayBuffer, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* ## Notes
	*
	* -   The returned ndarray view spans from the byteOffset to the end of the underlying ArrayBuffer and the two leading dimensions of the returned ndarray always have a size of one.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 1, 3 ]
	*/
	( buffer: ArrayBuffer, byteOffset: number, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param shape - ndarray shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8, [ 1, 2, 1 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 1 ]
	*/
	( buffer: ArrayBuffer, byteOffset: number, shape: Shape3D, options?: Options ): float64ndarray;

	/**
	* Creates a double-precision floating-point three-dimensional ndarray.
	*
	* @param buffer - underlying ArrayBuffer
	* @param byteOffset - integer byte offset specifying the location of the first element
	* @param K - number of elements in the first dimension
	* @param M - number of elements in the second dimension
	* @param N - number of elements in the last dimension
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
	* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns three-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	* var ArrayBuffer = require( '@stdlib/array/buffer' );
	*
	* var buf = new ArrayBuffer( 32 );
	* var arr = new Float64Tensor3D( buf, 8, 1, 2, 1 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 1, 2, 1 ]
	*/
	( buffer: ArrayBuffer, byteOffset: number, K: number, M: number, N: number, options?: Options ): float64ndarray;
}

/**
* Creates a double-precision floating-point three-dimensional ndarray.
*
* @param arg0 - shape, number of elements in the second dimension, array-like object, ArrayBuffer, or iterable
* @param arg1 - number of elements in the last dimension or integer byte offset specifying the location of the first element
* @param arg2 - ndarray shape or number of elements in the second dimension
* @param arg3 - number of elements in the last dimension
* @param options - function options
* @param options.readonly - boolean indicating whether to return a read-only three-dimensional ndarray
* @param options.mode - specifies how to handle indices which exceed ndarray dimensions
* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
* @param options.order - memory layout (either row-major or column-major)
* @returns three-dimensional ndarray
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new Float64Tensor3D();
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 0, 0, 0 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new Float64Tensor3D( [ 1, 2, 2 ] );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 1, 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new Float64Tensor3D( 1, 2, 2 );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 1, 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new Float64Tensor3D( [ [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] ] );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 1, 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Float64Tensor3D( buf, 8, [ 1, 2, 1 ] );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 1, 2, 1 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
* var ArrayBuffer = require( '@stdlib/array/buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Float64Tensor3D( buf, 8, 1, 2, 1 );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 1, 2, 1 ]
*/
declare var ctor: Float64Tensor3D;


// EXPORTS //

export = ctor;
